// Makes the demo account: a users row with no Twitch account, so it shows on
// User Management. Returns [error, username].
function badm_keys_make_demo(mysqli $conn, string $name): array {
    $name = strtolower(trim($name));
    // The username is also the channel's database name (usr_database.php).
    if (!preg_match('/^[a-z0-9_]{3,25}$/', $name)) return ['The demo account name must be 3 to 25 letters, numbers or underscores.', null];
    $st = $conn->prepare('SELECT 1 FROM users WHERE LOWER(username) = ? LIMIT 1');
    $st->bind_param('s', $name);
    $st->execute();
    $taken = $st->get_result()->num_rows > 0;
    $st->close();
    if ($taken) return ['A user named "' . $name . '" already exists. Pick another demo account name.', null];
    $apiKey = bin2hex(random_bytes(16));
    $image = 'https://cdn.botofthespecter.com/logo.png';
    $st = $conn->prepare("INSERT INTO users (username, access_token, refresh_token, api_key, profile_image, twitch_user_id, twitch_display_name, email, is_admin, new_media, is_demo) VALUES (?, '', '', ?, ?, '', ?, '', 0, 1, 1)");
    if (!$st) return ['Could not create the demo account: ' . $conn->error, null];
    $st->bind_param('ssss', $name, $apiKey, $image, $name);
    $ok = $st->execute();
    $err = $st->error;
    $st->close();
    if (!$ok) return ['Could not create the demo account: ' . $err, null];
    admin_audit_log('admin_demo_account_create', 'info', ['username' => $name], 'user', $name);
    badm_keys_demo_database($name);
    return [null, $name];
}
// The demo channel's own database, made the way the old dashboard makes one for
// every signed-in channel (same as User Databases). The admin session was
// already closed, so swapping the username here is never saved.
function badm_keys_demo_database(string $name): array {
    $prev = $_SESSION['username'] ?? null;
    $_SESSION['username'] = $name;
    ob_start();
    try {
        include '/var/www/dashboard/includes/usr_database.php';
    } catch (Throwable $e) {
        error_log('api_keys demo database for ' . $name . ': ' . $e->getMessage());
    }
    ob_end_clean();
    $_SESSION['username'] = $prev;
    return badm_keys_demo_seed($name);
}
// Sample data in the demo channel's own tables, so the pages it can see have
// something in them: custom commands, commands from made-up viewers, timed
// messages and known users with welcome messages. A table that already has rows
// is left alone, so running it again never duplicates or overwrites anything.
function badm_keys_demo_seed(string $name): array {
    if (!preg_match('/^[a-z0-9_]{3,25}$/', $name)) return [];
    include '/var/www/config/database.php';
    mysqli_report(MYSQLI_REPORT_OFF);
    $db = @new mysqli($db_servername ?? '', $db_username ?? '', $db_password ?? '', $name);
    if ($db->connect_error) {
        error_log('api_keys demo seed for ' . $name . ': ' . $db->connect_error);
        return [];
    }
    $db->set_charset('utf8mb4');
    $empty = function (string $table) use ($db): bool {
        $r = $db->query("SELECT 1 FROM `$table` LIMIT 1");
        if (!$r) return false;
        $none = $r->num_rows === 0;
        $r->free();
        return $none;
    };
    $added = [];
    if ($empty('custom_commands')) {
        $st = $db->prepare("INSERT INTO custom_commands (command, response, status, cooldown, permission) VALUES (?, ?, ?, ?, ?)");
        foreach ([
            ['hello', 'Hello and welcome to the stream! Grab a drink and say hi in chat.', 'Enabled', 15, 'everyone'],
            ['discord', 'Join the community Discord to hang out between streams.', 'Enabled', 30, 'everyone'],
            ['schedule', 'We stream Monday, Wednesday and Friday evenings.', 'Enabled', 30, 'everyone'],
            ['socials', 'Follow along on all the socials, links are in the panels below the stream.', 'Enabled', 30, 'everyone'],
            ['hydrate', 'Time for a water break! Stay hydrated, chat.', 'Enabled', 60, 'mod'],
            ['oldgiveaway', 'The giveaway has ended. Thanks to everyone who entered!', 'Disabled', 15, 'everyone'],
        ] as [$c, $r, $stt, $cd, $perm]) {
            $st->bind_param('sssis', $c, $r, $stt, $cd, $perm);
            $st->execute();
        }
        $st->close();
        $added[] = 'custom commands';
    }
    if ($empty('custom_user_commands')) {
        $st = $db->prepare("INSERT INTO custom_user_commands (command, response, status, cooldown, user_id) VALUES (?, ?, 'Enabled', ?, ?)");
        foreach ([
            ['panda', 'PixelPanda rolls into chat!', 15, 'pixelpanda'],
            ['owl', 'NightOwl is watching... always watching.', 30, 'nightowl_gg'],
            ['speedrun', 'RetroRunner says: any% or bust!', 15, 'retrorunner'],
            ['cozy', 'CozyCatLady brought snacks for everyone.', 20, 'cozycatlady'],
        ] as [$c, $r, $cd, $u]) {
            $st->bind_param('ssis', $c, $r, $cd, $u);
            $st->execute();
        }
        $st->close();
        $added[] = 'user commands';
    }
    if ($empty('timed_messages')) {
        $st = $db->prepare("INSERT INTO timed_messages (interval_count, chat_line_trigger, message, status, trigger_type) VALUES (?, ?, ?, ?, ?)");
        foreach ([
            [15, null, 'Enjoying the stream? Hit follow so you never miss one!', '1', 'timer'],
            [null, 40, 'Join the community Discord, type !discord for the link.', '1', 'chat_lines'],
            [30, 60, 'Remember to stretch and drink some water!', '1', 'both'],
            [45, null, 'Old sponsor message, switched off.', '0', 'timer'],
        ] as [$every, $lines, $msg, $stt, $type]) {
            $st->bind_param('iisss', $every, $lines, $msg, $stt, $type);
            $st->execute();
        }
        $st->close();
        $added[] = 'timed messages';
    }
    if ($empty('seen_users')) {
        $st = $db->prepare("INSERT INTO seen_users (username, welcome_message, status, first_seen, last_seen) VALUES (?, ?, ?, DATE_SUB(NOW(), INTERVAL ? DAY), DATE_SUB(NOW(), INTERVAL ? DAY))");
        foreach ([
            ['pixelpanda', 'Welcome back PixelPanda, the bamboo is ready!', 'True', 120, 1],
            ['nightowl_gg', 'The night owl has landed. Welcome back!', 'True', 90, 2],
            ['retrorunner', 'RetroRunner is here, time to go fast!', 'True', 60, 3],
            ['cozycatlady', 'Welcome back CozyCatLady, make yourself at home.', 'True', 45, 5],
            ['lurkingluke', null, 'True', 30, 7],
            ['bannedbob', 'This welcome message is switched off.', 'False', 20, 10],
        ] as [$u, $w, $stt, $first, $last]) {
            $st->bind_param('sssii', $u, $w, $stt, $first, $last);
            $st->execute();
        }
        $st->close();
        $added[] = 'known users';
    }
    $db->close();
    return $added;
}
// Applies the posted access fields to a key. $row is the key's current row.
function badm_keys_apply(mysqli $conn, array $row): array {
    $admin = admin_api_keys_flag($_POST['admin_access'] ?? 1);
    $app = admin_api_keys_flag($_POST['app_access'] ?? 0);
    $dash = admin_api_keys_flag($_POST['dashboard_access'] ?? 0);
    $password = (string) ($_POST['password'] ?? '');
    $channel = $row['channel'] ?? null;
    if ($password !== '' && strlen($password) < 6) return ['The password must be at least 6 characters.', null];
    if (($app || $dash) && empty($row['password']) && $password === '') return ['Set a password for Mobile app or Dashboard access.', null];
    if (($app || $dash) && empty($channel)) {
        [$err, $channel] = badm_keys_make_demo($conn, (string) ($_POST['demo_name'] ?? ''));
        if ($err !== null) return [$err, null];
    }
    $hash = $password !== '' ? password_hash($password, PASSWORD_ARGON2ID) : null;
    // A blank password keeps the stored one.
    $st = $conn->prepare('UPDATE admin_api_keys SET admin_access = ?, app_access = ?, dashboard_access = ?, channel = ?, password = COALESCE(?, password) WHERE service = ?');
    $st->bind_param('iiisss', $admin, $app, $dash, $channel, $hash, $row['service']);
    $ok = $st->execute();
    $st->close();
    if (!$ok) return ['Could not update key access.', null];
    admin_audit_log('admin_api_key_access', 'info', [
        'service' => $row['service'], 'admin_access' => $admin, 'app_access' => $app, 'dashboard_access' => $dash,
        'channel' => $channel, 'password_changed' => $hash !== null,
    ], 'admin_api_key', $row['service']);
    return [null, badm_keys_row($conn, $row['service'])];
}
badm_keys_ensure_access_columns($conn);
// POST create_key_access: create_key plus the access fields, in one go.
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['create_key_access'])) {
    $service = trim((string) ($_POST['service'] ?? ''));
    if ($service === '') badm_keys_json(['success' => false, 'message' => t('admin_api_keys_error_service_empty')]);
    if (badm_keys_row($conn, $service)) badm_keys_json(['success' => false, 'message' => 'A key for "' . $service . '" already exists.']);
    $app = admin_api_keys_flag($_POST['app_access'] ?? 0);
    $dash = admin_api_keys_flag($_POST['dashboard_access'] ?? 0);
    $password = (string) ($_POST['password'] ?? '');
    // Checked before anything is written, so a bad form makes no key.
    if (($app || $dash) && strlen($password) < 6) badm_keys_json(['success' => false, 'message' => $password === '' ? 'Set a password for Mobile app or Dashboard access.' : 'The password must be at least 6 characters.']);
    $apiKey = bin2hex(random_bytes(16));
    $wsA = admin_api_keys_flag($_POST['websocket_access'] ?? 0);
    $wsG = $wsA ? admin_api_keys_flag($_POST['websocket_global'] ?? 0) : 0;
    $st = $conn->prepare('INSERT INTO admin_api_keys (service, api_key, websocket_access, websocket_global) VALUES (?, ?, ?, ?)');
    $st->bind_param('ssii', $service, $apiKey, $wsA, $wsG);
    $ok = $st->execute();
    $err = $st->error;
    $st->close();
    if (!$ok) badm_keys_json(['success' => false, 'message' => t('admin_api_keys_error_create_failed', [$err])]);
    admin_audit_log('admin_api_key_create', 'info', ['service' => $service, 'websocket_access' => $wsA, 'websocket_global' => $wsG], 'admin_api_key', $service);
    [$err, $row] = badm_keys_apply($conn, badm_keys_row($conn, $service));
    if ($err !== null) {
        // The key exists now, without the access that failed.
        badm_keys_json(['success' => true, 'message' => t('admin_api_keys_msg_created') . ' ' . $err, 'api_key' => $apiKey, 'warning' => $err]);
    }
    badm_keys_json(['success' => true, 'message' => t('admin_api_keys_msg_created'), 'api_key' => $apiKey]);
}
// POST demo_data: fill (or finish making) the key's demo account: its channel
